insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 41, 'E Pedro lhe disse: Senhor, dizes tu esta parábola para nós, ou também para todos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 42, 'E o Senhor disse: Qual é, pois, o mordomo fiel e prudente, a quem [seu] senhor puser sobre seus servos, para que [lhes] dê alimento no tempo certo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 43, 'Bem-aventurado aquele servo ao qual, quando seu senhor vier, o achar fazendo assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 44, 'Em verdade vos digo, que o porá sobre todos os seus bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 45, 'Mas se aquele servo disser em seu coração: Meu senhor está demorando para vir; e começar a espancar aos servos e servas, e a comer, e a beber, e a se embebedar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 46, 'Virá o senhor daquele servo, no dia em que ele não espera, e na hora que ele não sabe; e será partido em dois, e porá sua porção com os incrédulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 47, 'E o servo que sabia a vontade de seu senhor, e não se preparou, nem fez conforme a sua vontade, será muito espancado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 48, 'Mas o que não sabia, e fez [coisas] dignas de pancadas, será pouco espancado. E a qualquer que muito for dado, muito se lhe pedirá, e ao que muito se confiou, muito mais lhe será exigido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 49, 'Eu vim para lançar fogo na terra; e o que mais posso querer, se já está aceso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 50, 'Porém há um batismo que tenho que ser batizado; e como me angustio até que se venha a cumprir!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 51, 'Vós pensais que vim para dar paz à terra? Não, eu vos digo; mas antes [vim para trazer] divisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 52, 'Porque daqui em diante cinco estarão divididos em uma casa; três contra dois, e dois contra três.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 53, 'O pai estará dividido contra o filho, e o filho contra o pai; a mãe contra a filha, e a filha contra a mãe; a sogra contra sua nora, e a nora contra sua sogra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 54, 'E ele dizia também para as multidões: Quando vedes a nuvem que vem do ocidente, logo dizeis: Lá vem chuva; E assim acontece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 55, 'E quando venta do sul, dizeis: Haverá calor; E assim acontece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 56, 'Hipócritas! Sabeis entender a aparência da terra e do céu; e como não entendeis este tempo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 57, 'E por que também não julgais por vós mesmos o que é justo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 58, 'Pois quando fores com teu adversário à autoridade, procura te livrares dele no caminho, para que ele não venha a te levar ao juiz, e o juiz te entregue ao oficial de justiça, e o oficial de justiça te lance na prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 12, 59, 'Eu te digo que não sairás dali enquanto não pagares até a última moeda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 1, 'E naquele mesmo tempo estavam ali presentes alguns, que lhe contavam dos galileus cujo sangue Pilatos tinha misturado com seus sacrifícios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 2, 'E respondendo Jesus, disse-lhes: Vós pensais que estes galileus foram mais pecadores, por terem sofrido estas coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 3, 'Não, eu vos digo; antes, se vós não vos arrependerdes, todos de modo semelhante perecereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 4, 'Ou aqueles dezoito, sobre os quais a torre em Siloé caiu, matando-os; pensais que eram mais culpados dos que todos as pessoas que moravam em Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 5, 'Não, eu vos digo; antes, se vós não vos arrependerdes, todos de modo semelhante perecereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 6, 'E dizia esta parábola: Um certo [homem] tinha uma figueira plantada em sua vinha, e veio até ela para buscar fruto, e não achou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 7, 'E disse ao que cuidava da vinha: Eis que há três anos, que venho para buscar fruto nesta figueira, e não [o] acho; corta-a; por que ainda ocupa inutilmente a terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 8, 'E respondendo ele, disse-lhe: Senhor, deixa-a [ainda] este ano, até que eu a escave ao redor, e a adube;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 9, 'E se der fruto, [deixa-a ficar] ; se não, tu a cortarás depois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 10, 'E ensinava em uma das sinagogas num sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 11, 'E eis que estava ali uma mulher, que havia dezoito anos que tinha um espírito de enfermidade; e andava encurvada, e de maneira nenhuma ela podia se endireitar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 12, 'E Jesus vendo-a, chamou-a para si, e disse-lhe: Mulher, livre estás de tua enfermidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 13, 'E pôs as mãos sobre ela, e logo ela se endireitou, e glorificava a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 14, 'E o chefe da sinagoga, irritado por Jesus ter curado no sábado, respondendo, disse à multidão: Há seis dias em que se deve trabalhar; nestes dias, pois, vinde para ser curados, e não no dia de sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 15, 'Porém o Senhor lhe respondeu, e disse: Hipócrita, no sábado cada um de vós não desata seu boi ou jumento da manjedoura, e o leva para dar de beber?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 16, 'E não convinha soltar desta ligadura no dia de sábado a esta [mulher] ,que é filha de Abraão, a qual, eis que Satanás já a havia ligado há dezoito anos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 17, 'E ele, dizendo estas coisas, todos seus adversários ficaram envergonhados; e todo o povo se alegrava de todas as coisas gloriosas que eram feitas por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 18, 'E dizia: A que o Reino de Deus é semelhante? E a que eu o compararei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 19, 'Semelhante é ao grão da mostarda, que um homem, tomando-o, lançou-o em sua horta; e cresceu, e fez-se uma grande árvore, e as aves dos céus fizeram ninhos em seus ramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 20, 'E disse outra vez: A que compararei o Reino de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 21, 'Semelhante é ao fermento, que a mulher, tomando-o, o escondeu em três medidas de farinha, até tudo ficar levedado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 22, 'E andava de cidade em cidade, e de aldeia em aldeia ensinando, e caminhando para Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 23, 'E disse-lhe um: Senhor, são também poucos os que se salvam? E ele lhes disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 24, 'Trabalhai para entrar pela porta estreita; porque eu vos digo, [que] muitos procuraram entrar, e não puderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 25, 'Porque quando o chefe da casa se levantar, e fechar a porta, e se estiverdes de fora, e começardes a bater à porta, dizendo: Senhor, senhor, abre-nos! E respondendo ele, vos disser: Não vos conheço, [nem sei] de onde vós sois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 26, 'Então começareis a dizer: Em tua presença temos comido e bebido, e tens ensinado em nossas ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 27, 'E ele dirá: Digo-vos que não vos conheço, [nem sei] de onde vós sois; afastai-vos de mim, vós todos praticantes de injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 28, 'Ali haverá choro e ranger de dentes, quando virdes a Abraão, a Isaque, a Jacó, e a todos os profetas no Reino de Deus; mas vós [sendo] lançados fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 29, 'E virão [pessoas] do oriente, e do ocidente, e do norte, e do sul, e se sentarão [à mesa] no Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 30, 'E eis que há [alguns] dos últimos que serão primeiros, e há [alguns] dos primeiros que serão últimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 31, 'Naquele mesmo dia, chegaram uns fariseus, dizendo-lhe: Sai, e vai-te daqui, porque Herodes quer te matar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 32, 'E disse-lhes: Ide, e dizei a aquela raposa: eis que expulso demônios, e faço curas hoje e amanhã, e ao terceiro dia eu terei completado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 33, 'Porém é necessário que hoje, e amanhã, e no [dia] seguinte eu caminhe; porque um profeta não pode morrer fora de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 34, 'Jerusalém, Jerusalém, que matas aos profetas, e apedrejas aos que te são enviados: quantas vezes eu quis juntar teus filhos, como a galinha junta seus pintos debaixo de suas asas, e não quisestes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 13, 35, 'Eis que vossa casa é deixada deserta para vós. E em verdade vos digo, que não me vereis até que venha [o tempo] em que digais: Bendito aquele que vem no nome do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 1, 'E aconteceu que, entrando ele num sábado para comer pão na casa de um dos chefes dos fariseus, eles estavam o observando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 2, 'E eis que um certo homem com o corpo inchado estava ali diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 3, 'E respondendo Jesus, falou aos estudiosos da Lei, e aos fariseus, dizendo: É lícito curar no sábado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 4, 'Porém eles ficaram calados; e ele, tomando [-o] ,o curou, e [o] despediu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 5, 'E ele, respondendo-lhes, disse: De qual que vós cairá o jumento, ou o boi em algum poço que, [mesmo] no sábado, não o tire logo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 6, 'E nada podiam lhe responder a estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 7, 'E vendo como os convidados escolhiam os primeiros assentos, disse-lhes uma parábola:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 8, 'Quando fores convidados para o casamento de alguém, não te sentes no primeiro assento, para que não [aconteça de] se outro convidado mais digno que tu estiver,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 9, 'E venha o que convidou a ti e a ele, e te diga: Dá lugar a este; E então, com vergonha, tenhas que tomar o último lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 10, 'Mas quando fores convidado, vai, e senta-te no último lugar; para que quando vier o que te convidou, te diga: Amigo, sobe para [este assento] melhor. Então terás honra diante dos que estiverem sentados contigo [à mesa] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 11, 'Porque qualquer que exaltar a si mesmo, e aquele que humilhar a si mesmo, será exaltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 12, 'E dizia também ao que tinha lhe convidado: Quando fizeres um jantar, ou uma ceia, não chames a teus amigos, nem a teus irmãos, nem a teus parentes, nem a [teus] vizinhos ricos, para que eles também em algum tempo não te convidem de volta, e tu sejas recompensado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 13, 'Mas quando fizeres convite, chama aos pobres, aleijados, mancos [e] cegos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 14, 'E serás bem-aventurado, porque não eles não têm como te recompensar; pois tu serás recompensado na ressurreição dos justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 15, 'E um dos que juntamente estavam sentados [à mesa] , ouvindo isto, disse-lhe: Bem-aventurado aquele que comer pão no Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 16, 'Porém ele lhe disse: Um certo homem fez um grande jantar, e convidou a muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 17, 'E na hora do jantar, mandou seu servo para dizer aos convidados: Vinde, que tudo já está preparado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 18, 'E cada um deles todos começou a dar desculpas. O primeiro lhe disse: Comprei um campo, e tenho que ir vê-lo; peço-te desculpas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 19, 'E outro disse: Comprei cinco pares de bois, e vou testá-los; peço-te desculpas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 20, 'E outro disse: Casei-me [com] uma mulher, e portanto não posso vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 21, 'E aquele servo, ao voltar, anunciou estas coisas a seu senhor. Então o chefe da casa, irritado, disse a seu servo: Sai depressa pelas ruas e praças da cidade, e traze aqui aos pobres, e aleijados, e mancos e cegos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 22, 'E o servo disse: Senhor, está feito como mandaste, e ainda há lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 23, 'E o senhor disse ao servo: Sai pelos caminhos, e trilhas, e força-os a entrar, para que minha casa se encha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 24, 'Porque eu vos digo, que nenhum daqueles homens que foram convidados experimentará da minha ceia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 25, 'E muitas multidões iam com ele; e virando-se, disse-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 26, 'Se alguém vier a mim, e não odiar a seu pai, e mãe, e mulher, e filhos, e irmãos, e irmãs, e ainda também sua própria vida, não pode ser meu discípulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 27, 'E qualquer que não levar sua cruz, e vier após mim, não pode ser meu discípulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 28, 'Porque qual de vós, querendo edificar uma torre, não se senta primeiro para fazer as contas dos gastos, [para ver] se tem o [suficiente] para a completar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 29, 'Para que não aconteça que, depois de ter posto seu fundamento, e não podendo a completar, comecem a escarnecer dele todos os que [o] virem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 30, 'Dizendo: Este homem começou a construir, e não pôde terminar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 31, 'Ou qual rei, indo a guerra para lutar contra outro rei, não se senta primeiro para consultar, se pode ir ao encontro com dez mil [soldados] , vindo contra ele vinte mil?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 32, 'Se não [puder] , estando o outro ainda longe, manda [-lhe] representantes diplomáticos, e roga pela paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 33, 'Assim, portanto, qualquer de vós que não renuncia a tudo, não pode ser meu discípulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 34, 'Bom é o sal; porém se o sal perder o sabor, com o que ele será temperado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 14, 35, 'Nem para a terra, nem para adubo serve; lançam-no fora. Quem tem ouvidos para ouvir, ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 1, 'E chegavam-se a ele todos os publicanos e pecadores para o ouvirem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 2, 'E os fariseus e escribas murmuravam, dizendo: Este recebe aos pecadores, e come com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 3, 'E ele lhes propôs esta parábola, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 4, 'Quem de vós, tendo cem ovelhas, e perdendo uma delas, não deixa no deserto as noventa e nove, e vai em [busca] da perdida, até que a encontre?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 5, 'E encontrando-a, [não] a ponha sobre seus ombros, com alegria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 6, 'E vindo para casa, [não] convoque aos amigos, e vizinhos, dizendo-lhes: Alegrai-vos comigo, porque já achei minha ovelha perdida?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 7, 'Digo-vos, que assim haverá mais alegria no céu por um pecador que se arrepende, do que por noventa e nove justos que não precisam de arrependimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 8, 'Ou que mulher, tendo dez moedas de prata, se perder a uma moeda, não acende a lâmpada, e varre a casa, e busca cuidadosamente até [a] achar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 9, 'E achando [-a] , [não] chame as amigas e as vizinhas, dizendo: Alegrai-vos comigo, porque já achei a moeda perdida!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 10, 'Assim vos digo, que há alegria diante dos anjos de Deus por um pecador que se arrepende.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 11, 'E disse: Um certo homem tinha dois filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 12, 'E disse o mais jovem deles ao pai: Pai, dá-me a parte dos bens que [me] pertencem. E ele lhe repartiu os bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 13, 'E depois de não muitos dias, o filho mais jovem, juntando tudo, partiu-se para uma terra distante, e ali desperdiçou seus bens, vivendo de forma irresponsável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 14, 'E ele, tendo já gastado tudo, houve uma grande fome naquela terra, e ele começou a sofrer necessidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 15, 'E foi, se chegou a um dos cidadãos daquela terra; e [este] o mandou a seus campos para alimentar porcos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 16, 'E ele ficava com vontade de encher seu estômago com os grãos que os porcos comiam, mas ninguém [as] dava para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 17, 'E ele, pensando consigo mesmo, disse: Quantos empregados de meu pai tem pão em abundância, e eu [aqui] morro de fome!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 18, 'Eu levantarei, e irei a meu pai, e lhe direi: Pai, pequei contra o céu, e diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 19, 'E já não sou digno de ser chamado teu filho; faze-me como a um de teus empregados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 20, 'E levantando-se, foi a seu pai. E quando ainda estava longe, o seu pai o viu, e teve compaixão dele; e correndo, caiu ao seu pescoço, e o beijou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 21, 'E o filho lhe disse: Pai, pequei contra o céu, e diante de ti; e já não sou digno de ser chamado teu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 22, 'Mas o pai disse a seus servos: Trazei a melhor roupa, e o vesti; e ponde um anel em sua mão, e sandálias nos [seus] pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 23, 'E trazei o bezerro engordado, e o matai; e comamos, e nos alegremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 24, 'Porque este meu filho estava morto, e reviveu; tinha se perdido, e foi achado. E começaram a se alegrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 25, 'E seu filho mais velho estava no campo; e quando veio, chegou perto da casa, ouviu a música, e as danças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 26, 'E chamando para si um dos servos, perguntou-lhe: O que era aquilo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 27, 'E ele lhe disse: Teu irmão chegou; e teu pai matou o bezerro engordado, porque ele voltou são.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 28, 'Porém ele se irritou, e não queria entrar. Então o seu pai, saindo, rogava-lhe [que entrasse] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 29, 'Mas [o filho] respondendo, disse ao pai: Eis que eu te sirvo há tantos anos, e nunca desobedeci tua ordem, e nunca me deste um cabrito, para que eu me alegrasse com meus amigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 30, 'Porém, vindo este teu filho, que gastou teus bens com prostitutas, tu lhe mataste o bezerro engordado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 31, 'E ele lhe disse: Filho, tu sempre estás comigo, e todas as minhas coisas são tuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 15, 32, 'Mas era necessário se alegrar e animar; porque este teu irmão estava morto, e reviveu; e tinha se perdido, e foi encontrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 1, 'E dizia também a seus discípulos: Havia um certo homem rico, o qual tinha um mordomo; e este lhe foi acusado de fazer perder seus bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 2, 'E ele, chamando-o, disse-lhe: Como ouço isto sobre ti? Presta contas de teu trabalho, porque não poderás mais ser [meu] mordomo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 3, 'E disse o mordomo para si mesmo: O que farei, agora que meu senhor está me tirando o trabalho de mordomo? Cavar eu não posso; mendigar eu tenho vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 4, 'Eu sei o que farei, para que, quando eu for expulso do meu trabalho de mordomo, me recebam em suas casas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 5, 'E chamando a si a cada um dos devedores de seu senhor, disse ao primeiro: Quanto deves a meu senhor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 6, 'E ele disse: Cem medidas de azeite. E disse-lhe: Pega a tua conta, senta, e escreve logo cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 7, 'Depois disse a outro: E tu, quanto deves? E ele disse: Cem volumes de trigo. E disse-lhe: Toma tua conta, e escreve oitenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 8, 'E aquele senhor elogiou o injusto mordomo, por ter feito prudentemente; porque os filhos deste mundo são mais prudentes do que os filhos da luz com esta geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 9, 'E eu vos digo: fazei amigos para vós com as riquezas da injustiça, para que quando vos faltar, vos recebam nos tabernáculos eternos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 10, 'Quem é fiel no mínimo, também é fiel no muito; e quem é injusto no mínimo, também é injusto no muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 11, 'Pois se nas riquezas da injustiça não fostes fiéis, quem vos confiará as verdadeiras [riquezas] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 12, 'E se nas [coisas] dos outros não fostes fiéis, quem vos dará o que é vosso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 13, 'Nenhum servo pode servir a dois senhores; porque ou irá odiar a um, e a amar ao outro; ou irá se achegar a um, e desprezar ao outro. Não podeis servir a Deus e às riquezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 14, 'E os fariseus também ouviram todas estas coisas, eles que eram avarentos. E zombaram dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 15, 'E disse-lhes: Vós sois os que justificais a vós mesmos diante dos seres humanos; mas Deus conhece vossos corações. Porque o que é excelente para os seres humanos é odiável diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 16, 'A Lei e os profetas [foram] até João; desde então, o Reino de Deus é anunciado, todo homem [tenta entrar] nele pela força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 17, 'E é mais fácil passar o céu e a terra do que cair um traço de alguma letra da Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 18, 'Qualquer que deixa sua mulher, e casa com outra, adultera; e qualquer que se casa com a deixada pelo marido, [também] adultera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 19, 'Havia porém um certo homem rico, e vestia-se de púrpura, e de linho finíssimo, e festejava todo dia com luxo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 20, 'Havia também um certo mendigo, de nome Lázaro, o qual ficava deitado à sua porta cheio de feridas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 21, 'E desejava se satisfazer com as migalhas que caíam da mesa do rico; porém vinham também os cães, e lambiam suas feridas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 22, 'E aconteceu que o mendigo morreu, e foi levado pelos anjos para o colo de Abraão. E o rico também morreu, e foi sepultado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 23, 'E estando no Xeol em tormentos, ele levantou seus olhos, e viu a Abraão de longe, e a Lázaro junto dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 24, 'E ele, chamando, disse: Pai Abraão, tem misericórdia de mim, e manda a Lázaro que molhe a ponta de seu dedo na água, e refresque a minha língua; porque estou sofrendo neste fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 25, 'Porém Abraão disse: Filho, lembra-te que em tua vida recebeste teus bens, e Lázaro do mesmo jeito [recebeu] males. E agora este é consolado, e tu [és] atormentado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 26, 'E, além de tudo isto, um grande abismo está posto entre nós e vós, para os que quisessem passar daqui para vós não possam; nem também os daí passarem para cá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 27, 'E disse ele: Rogo-te, pois, ó pai, que o mandes à casa de meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 28, 'Porque tenho cinco irmãos, para que lhes dê testemunho; para que também não venham para este lugar de tormento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 29, 'Disse-lhe Abraão: Eles têm a Moisés e aos profetas, ouçam-lhes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 30, 'E ele disse: Não, pai Abraão; mas se alguém dos mortos fosse até eles, eles se arrependeriam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 16, 31, 'Porém [Abraão] lhe disse: Se não ouvem a Moisés e aos profetas, também não se deixariam convencer, ainda que alguém ressuscite dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 1, 'E disse aos discípulos: É impossível que não venham tentações para o pecado, mas ai [daquele] por quem [essas tentações] vierem!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 2, 'Melhor lhe seria que lhe atasse ao pescoço uma grande pedra de moinho, e fosse lançado no mar, do que conduzir ao pecado um destes pequenos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 3, 'Olhai por vós. E se teu irmão pecar contra ti, repreende-o; e se ele se arrepender, perdoa-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 4, 'E se pecar contra ti sete vezes ao dia, e se sete vezes ao dia voltar a ti, dizendo: Estou arrependido. Perdoa-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 5, 'E os apóstolos disseram ao Senhor: Acrescenta-nos fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 6, 'E o Senhor disse: Se tivésseis fé como um grão de mostarda, diríeis a esta árvore de amoras: Arranca-te daqui pelas tuas raízes, e planta-te no mar, ela vos obedeceria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 7, 'E qual de vós terá um servo, lavrando ou apascentando [gado] que, voltando do campo, logo lhe diga: Chega, e senta [à mesa] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 8, 'E não lhe diga antes: Prepara-me o jantar, e apronta-te, e serve-me, até que eu tenha comido e bebido; e depois, que tu comas e bebas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 9, 'Por acaso [o senhor] agradece a tal servo, porque fez o que lhe foi mandado? Acho que não.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 10, 'Assim também vós, quando fizerdes tudo o que vos for mandado, dizei: Somos servos inúteis, porque fizemos [somente] o que devíamos fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 11, 'E aconteceu que, indo ele para Jerusalém, passou por meio da Samaria e da Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 12, 'E entrando em uma certa aldeia, saíram-lhe ao encontro dez homens leprosos, os quais pararam de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 13, 'E levantaram a voz, dizendo: Jesus, Mestre, tem misericórdia de nós!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 14, 'E ele, vendo-os, disse-lhes: Ide, e mostrai-vos aos sacerdotes.E aconteceu que, enquanto eles iam, ficaram limpos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 15, 'E vendo um deles que estava são, voltou, glorificando a Deus a alta voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 16, 'E caiu com o rosto a seus pés, agradecendo-lhe; e este era samaritano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 17, 'E respondendo Jesus, disse: Não foram os dez limpos? E onde estão os nove?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 18, 'Não houve quem voltasse para dar glória a Deus, a não ser este estrangeiro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 19, 'E disse-lhe: Levanta-te, e vai; tua fé te salvou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 20, 'E perguntado pelos fariseus [sobre] quando o Reino de Deus viria, respondeu-lhes, e disse: O Reino de Deus não vem com aparência visível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 21, 'Nem dirão: Eis aqui, ou Eis ali, porque eis que o Reino de Deus está entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 22, 'E disse aos discípulos: Dias virão, quando desejareis ver um dos dias do Filho do homem, e não [o] vereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 23, 'E vos dirão: Eis que [ele está] aqui, ou Eis que [ele está] ali, não vades, nem sigais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 24, 'Porque como o relâmpago, que relampeja desde o começo do céu, e brilha até ao fim do céu, assim será também o Filho do homem em seu dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 25, 'Mas é necessário primeiro sofrer muito, e ser rejeitado por esta geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 26, 'E como aconteceu nos dias de Noé, assim será também nos dias do Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 27, 'Comiam, bebiam, se casavam, e se davam em casamento, até o dia em que Noé entrou na arca; e veio o dilúvio, e destruiu a todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 28, 'Como também da mesma maneira aconteceu nos dias de Ló, comiam, bebiam, compravam, vendiam, plantavam, [e] construíam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 29, 'Mas o dia em que Ló saiu de Sodoma, choveu fogo e enxofre do céu, e destruiu a todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 30, 'Assim será [também] no dia em que o Filho do homem se manifestar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 31, 'Naquele dia, o que estiver no telhado, e suas ferramentas em casa, não desça para pegá-las; e o que [estiver] no campo, não volte para trás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 32, 'Lembrai-vos da mulher de Ló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 33, 'Qualquer que procurar salvar sua vida a perderá; e qualquer que a perder, irá salvá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 34, 'Digo-vos que naquela noite, dois estarão em uma cama; um será tomado, e o outro será deixado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 35, 'Duas estarão juntas moendo; uma será tomada, e a outra será deixada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 36, 'Dois estarão no campo; um será tomado, e o outro será deixado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 17, 37, 'E respondendo, disseram-lhe: Onde, Senhor?E ele lhes disse: Onde estiver o corpo, ali os abutres se juntarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 1, 'E [Jesus] lhes disse também uma parábola [sobre] o dever de sempre orar, e nunca se cansar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 2, 'Dizendo: Havia um certo juiz em uma cidade, que não temia a Deus, nem respeitava pessoa alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 3, 'Havia também naquela mesma cidade uma certa viúva, e vinha até ele, dizendo: Faze-me justiça com meu adversário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 4, 'E por um [certo] tempo ele não quis; mas depois disto, disse para si: Ainda que eu não tema a Deus, nem respeite pessoa alguma,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 5, 'Porém, porque esta viúva me incomoda, eu lhe farei justiça, para que ela pare de vir me chatear.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 6, 'E disse o Senhor: Ouvi o que diz o juiz injusto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 7, 'E Deus não fará justiça para seus escolhidos, que clamam a ele de dia e de noite? Demorará com eles?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 8, 'Digo-vos que depressa lhes fará justiça. Porém, quando o Filho do homem vier, por acaso ele achará fé na terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 9, 'E disse também a uns, que tinham confiança de si mesmos que eram justos, e desprezavam aos outros, esta parábola:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 10, 'Dois homens subiram ao Templo para orar, um fariseu, e o outro publicano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 11, 'O fariseu, estando de pé, orava consigo desta maneira: Ó Deus, eu te agradeço, porque não sou como os outros homens, ladrões, injustos e adúlteros; nem [sou] como este publicano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 12, 'Jejuo duas vezes por semana, [e] dou dízimo de tudo quanto possuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 13, 'E o publicano, estando em pé de longe, nem mesmo queria levantar os olhos ao céu, mas batia em seu peito, dizendo: Ó Deus, tem misericórdia de mim, [que sou] pecador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 14, 'Digo-vos que este desceu mais justificado à sua casa do que aquele outro; porque qualquer que a si mesmo se exalta, será humilhado; e qualquer que a si mesmo se humilha, será exaltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 15, 'E traziam-lhe também crianças pequenas, para que as tocasse; e os discípulos, vendo, os repreendiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 16, 'Mas Jesus, chamando-lhes para si, disse: Deixai as crianças virem a mim, e não as impeçais; porque das tais é o Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 17, 'Em verdade vos digo, que qualquer que não receber o Reino de Deus como criança, não entrará nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 18, 'E um certo líder lhe perguntou, dizendo: Bom mestre, o que tenho que fazer para herdar a vida eterna?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 19, 'E Jesus lhe disse: Por que me chamas de bom? Ninguém [é] bom, a não ser um: Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 20, 'Tu sabes os mandamentos: não adulterarás, não matarás, não furtarás, não darás falso testemunho, honra a teu pai e a tua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 21, 'E ele disse: Todas estas coisas tenho guardado desde minha juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 22, 'Porém Jesus, ouvindo isto, disse-lhe: Ainda uma coisa te falta: vende tudo quanto tens, e reparte-o entre os pobres, e terás um tesouro no céu; e vem, segue-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 23, 'Mas ele, ouvindo isto, ficou muito triste, porque era muito rico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 24, 'E vendo Jesus que ele tinha ficado muito triste, disse: Como é difícil os que têm [muitos] bens entrarem no Reino de Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 25, 'Porque é mais fácil um camelo entrar pelo olho de uma agulha do que um rico entrar no Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 26, 'E os que ouviram [isto] ,disseram: Quem então pode se salvar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 27, 'E ele disse: As coisas que são impossíveis para os seres humanos são possíveis para Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 28, 'E Pedro disse: Eis que deixamos tudo, e temos te seguido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 29, 'E ele lhes disse: Em verdade vos digo, que há ninguém que, tenha deixado casa, ou pais, ou irmãos, ou mulher, ou filhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 30, 'Que não venha a receber de volta muito mais nestes tempos, e nos tempos vindouros [receba] a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 31, 'E tomando consigo aos doze, disse-lhes: Eis que estamos subindo a Jerusalém, e se cumprirá no Filho do homem tudo o que [está] escrito pelos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 32, 'Porque ele será entregue aos gentios, e escarnecido, injuriado e cuspido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 33, 'E [depois de] açoitá-lo, o matarão; e ao terceiro dia ressuscitará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 34, 'E eles nada entendiam destas coisas; e esta palavra lhes era oculta; e não entendiam o que estava sendo lhes dito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 35, 'E aconteceu que ele, chegando perto de Jericó, estava um cego sentado junto ao caminho, mendigando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 36, 'E este, ouvindo a multidão passar, perguntou: O que era aquilo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 37, 'E disseram-lhe que Jesus Nazareno estava passando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 38, 'Então clamou, dizendo: Jesus, Filho de Davi, tem misericórdia de mim!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 39, 'E os que estavam mais a frente o repreendiam, para que calasse; porém ele clamava ainda mais: Filho de Davi, tem misericórdia de mim!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 40, 'Então Jesus, parando, mandou que o trouxessem para si; e chegando ele, perguntou-lhe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 41, 'Dizendo: Que queres que eu te faça?E ele disse: Senhor, que eu veja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 42, 'E Jesus lhe disse: Vê, tua fé te salvou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 18, 43, 'E logo ele viu, e o seguia, glorificando a Deus. E o todo o povo, vendo [isto] , dava louvores a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 1, 'E [Jesus] entrou e foi passando por Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 2, 'E eis que havia ali um homem, chamado pelo nome de Zaqueu, e este era chefe dos publicanos, e era rico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 3, 'E procurava ver quem era Jesus, e não podia, por causa da multidão, pois era pequeno de altura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 4, 'E correndo com antecedência, subiu em uma árvore de frutos que parecem figos, para o ver; porque ele passaria por ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 5, 'E quando Jesus chegou a aquele lugar, olhando para cima, o viu, e disse-lhe: Zaqueu, apressa-te, e desce; porque hoje é necessário que eu fique em tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 6, 'E apressando-se, desceu, e o recebeu com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 7, 'E todos, vendo [isto] , murmuravam, dizendo: Ele entrou para se hospedar com um homem pecador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 8, 'E Zaqueu, levantando-se, disse ao Senhor: Senhor, eis que dou a metade de meus bens aos pobres; e se eu consegui algo enganando a alguém, eu [o] devolvo quatro vezes mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 9, 'E Jesus lhe disse: Hoje houve salvação nesta casa, porque ele também é filho de Abraão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 10, 'Porque o Filho do homem veio para buscar, e para salvar o que tinha se perdido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 11, 'E ouvindo eles estas coisas, [Jesus] prosseguiu, e disse uma parábola, porque estava perto de Jerusalém, e pensavam que logo o Reino seria manifesto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 12, 'Disse, pois: Um certo homem nobre partiu para uma terra distante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 13, 'E chamando dez servos seus, deu-lhes dez minas, e disse-lhes: Investi até que eu venha;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 14, 'E seus cidadãos o odiavam; e mandaram representantes depois dele, dizendo: Não queremos que este reine sobre nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 15, 'E aconteceu que, quando ele voltou, tendo tomado o reino, disse que lhe chamassem a aqueles servos, a quem tinha dado o dinheiro, para saber o que cada um tinha ganho fazendo investimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 16, 'E veio o primeiro, dizendo: Senhor, tua mina rendeu outras dez minas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 17, 'E ele lhe disse: Ótimo, bom servo! Por teres sido fiel no pouco, terás autoridade sobre dez cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 18, 'E veio o segundo, dizendo: Senhor, tua mina rendeu cinco minas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 19, 'E disse também a este: E tu [governarás] cinco cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 20, 'E veio outro, dizendo: Eis aqui tua mina, que guardei em um lenço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 21, 'Porque tive medo de ti, que és um homem rigoroso, que tomas o que não puseste, e colhes o que não semeaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 22, 'Porém ele lhe disse: Servo mau, por tua boca eu te julgarei; tu sabias que eu era um homem rigoroso, que tomo o que não pus, e que colho o que não semeei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 23, 'Por que, então, não puseste meu dinheiro no banco; e quando eu viesse, o receberia de volta com juros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 24, 'E disse aos que estavam com ele: Tirai-lhe a mina, e dai-a ao que tem as dez minas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 25, 'E eles lhe disseram: Senhor, ele [já] tem dez minas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 26, '[O senhor respondeu:] Porque eu vos digo, que todo aquele que tiver, lhe será dado; mas ao que não tiver, até o que tem, lhe será tirado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 27, 'Porém a aqueles meus inimigos, que não quiseram que eu reinasse sobre eles, trazei [- os] aqui, e matai [-os] diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 28, 'E dito isto, ele foi caminhando adiante, subindo para Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 29, 'E aconteceu que, chegando perto de Betfagé, e de Betânia, ao monte chamado das Oliveiras, mandou a dois de seus discípulos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 30, 'Dizendo: Ide à aldeia que está em frente; onde, ao entrardes, achareis um potro atado, em que ninguém jamais se sentou; soltai-o, e trazei [-o] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 31, 'E se alguém vos perguntar: Por que [o] soltais? Direis assim a ele: Porque o Senhor precisa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 32, 'E indo os que tinham sido mandados, acharam como lhes disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 33, 'E soltando o potro, seus donos lhe disseram: Por que soltais o potro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 34, 'E eles disseram: O Senhor precisa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 35, 'E o trouxeram a Jesus; e lançando suas roupas sobre o potro, puseram Jesus montado nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 36, 'E indo ele andando, estendiam suas roupas pelo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 37, 'E quando já chegava perto da descida do monte das Oliveiras, toda a multidão de discípulos, com alegria começou a louvar a Deus em alta voz, por todas as maravilhas que tinham visto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 38, 'Dizendo: Bendito o Rei que vem em nome do Senhor; paz no céu, e glória nas alturas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 39, 'E alguns dos fariseus da multidão lhe disseram: Mestre, repreende a teus discípulos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 40, 'E respondendo ele, disse-lhes: Digo-vos, que se estes se calarem, as pedras clamariam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 41, 'E quando já estava chegando, viu a cidade, e chorou por causa dela,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 42, 'Dizendo: Ah, se tu também conhecesses, pelo menos neste teu dia, aquilo que lhe traria paz! Mas agora [isto] está escondido de teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 43, 'Porque dias virão sobre ti, em que teus inimigos lhe cercarão com barricadas, e ao redor te sitiarão, e lhe pressionarão por todos os lados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 44, 'E derrubarão a ti, e a teus filhos; e não deixarão em ti pedra sobre pedra, porque não conheceste o tempo em que foste visitada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 45, 'E entrando no Templo, começou a expulsar a todos os que vendiam e compravam ali,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 46, 'Dizendo-lhes: Está escrito: Minha casa é casa de oração; Mas vós a tendes feito um esconderijo de ladrões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 47, 'E ensinava diariamente no Templo; e os chefes dos sacerdotes, e os escribas, e os chefes do povo, procuravam matá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 19, 48, 'E não achavam como fazer, porque todo o povo o ouvia com muita atenção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 1, 'E aconteceu, num daqueles dias que, enquanto ele estava ensinando ao povo no Templo, e anunciando o Evangelho, vieram até ele os chefes dos sacerdotes, e os escribas com os anciãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 2, 'E falaram-lhe, dizendo: Dize-nos, com que autoridade fazes estas coisas? Ou quem é o que te deu esta autoridade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 3, 'E respondendo ele, disse-lhes: Também eu vos perguntarei algo, e dizei-me:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 4, 'O batismo de João era do céu, ou dos homens?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 5, 'E eles discutiam entre si, dizendo: Se dissermos: Do céu, ele nos dirá: Por que, então, vós não [o] crestes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 6, 'E se dissermos: Dos homens, todo o povo nos apedrejará; pois estão convencidos de que João era profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 7, 'E responderam que não sabiam de onde [era] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 8, 'E Jesus lhes disse: Nem eu vos direi com que autoridade eu faço estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 9, 'E começou a dizer ao povo esta parábola: Um certo homem plantou uma vinha, e a arrendou a [uns] lavradores, e viajou para outro país por muito tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 10, 'E certo tempo [depois] mandou um servo aos lavradores, para que lhe dessem do fruto da vinha; mas os lavradores, espancando-o, mandaram [-no] sem coisa alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 11, 'E voltou a mandar outro servo; mas eles, espancando e humilhando também [a ele] ,o mandaram sem nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 12, 'E voltou a mandar ao terceiro; mas eles, ferindo também a este, [o] expulsaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 13, 'E o senhor da vinha disse: Que farei? Mandarei a meu filho amado; talvez quando o verem, [o] respeitarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 14, 'Mas os lavradores, vendo-o, discutiram entre si, dizendo: Este é o herdeiro; vamos matá-lo, para que a herança venha a ser nossa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 15, 'E expulsando-o da vinha, [o] mataram. O que, então, lhes fará o senhor da vinha?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 16, 'Virá, e destruirá a estes lavradores, e dará a vinha a outros.E eles, ouvindo isto, disseram: Que [isto] nunca aconteça!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 17, 'Mas [Jesus] ,olhando para eles, disse: Por que, então, isto está escrito: A pedra que os construtores rejeitaram, essa foi posta como a principal da esquina?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 18, 'Todo aquele que cair sobre aquela pedra, se quebrará em pedaços; e aquele sobre quem ela cair, se fará pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 19, 'E os chefes dos sacerdotes e os escribas queriam detê-lo naquela mesma hora, mas temiam ao povo; porque entenderam que foi contra eles que ele tinha dito a parábola.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 20, 'E, observando-o, mandaram espiões, que fingissem ser justos, para o pegarem por meio de algo que ele dissesse, e o entregarem ao poder e autoridade do governador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 21, 'E perguntaram-lhe, dizendo: Mestre, nós sabemos que falas e ensinas corretamente, e que não te importas com as aparências, mas na verdade tu ensinas o caminho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 22, 'É lícito para nós dar tributo a César, ou não?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 23, 'E ele, entendendo a astúcia deles, disse-lhes: Por que me tentais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 24, 'Mostrai-me uma moeda; ela tem a imagem e a inscrição de quem?E eles, respondendo, disseram: De César.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 25, 'Então lhes disse: Dai pois a César o que [é] de César, e a Deus o que [é] de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 26, 'E não puderam lhe pegar em algo que ele tenha dito diante do povo; e maravilhados de sua resposta, calaram-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 27, 'E chegando-se alguns dos saduceus, que negam haver a ressurreição, perguntaram-lhe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 28, 'Dizendo: Mestre, Moisés nos escreveu, que se o irmão de alguém morrer, tendo mulher, e morrer sem filhos, o irmão deve tomar a mulher, e gerar descendência a seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 29, 'Houve, pois, sete irmãos, e o primeiro tomou mulher, e morreu sem filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 30, 'E o segundo a tomou; e [também] este morreu sem filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 31, 'E o terceiro a tomou, e assim também os sete, e não deixaram filhos, e morreram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 32, 'E por fim, depois de todos, morreu também a mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 33, 'Na ressurreição, pois, ela será mulher de qual deles? Pois os sete a tiveram por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 34, 'E respondendo Jesus, disse-lhes: Os filhos destes tempos se casam, e se dão em casamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 35, 'Mas os que forem considerados dignos de alcançarem aqueles tempos futuros, e da ressurreição dos mortos, nem se casarão, nem se darão em casamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 36, 'Porque já não podem mais morrer; pois são iguais aos anjos; e são filhos de Deus, pois são filhos da ressurreição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 37, 'E até Moisés mostrou, junto à sarça, que os mortos ressuscitam, quando ele chama ao Senhor de Deus de Abraão, e Deus de Isaque, e Deus de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 38, 'Ora, ele não é Deus de mortos, mas de vivos; pois todos vivem por causa dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 39, 'E alguns dos escribas, respondendo, disseram: Mestre, bem disseste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 40, 'E não ousavam lhe perguntar mais nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 41, 'E ele lhes disse: Como dizem que o Cristo é filho de Davi?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 42, 'Pois o próprio Davi diz no livro dos Salmos: Disse o Senhor a meu Senhor: Senta-te à minha direita,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 43, 'Até que eu ponha teus inimigos por escabelo de teus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 44, 'Se Davi o chama de Senhor, como, então, é seu filho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 45, 'Enquanto todo o povo estava ouvindo, ele disse a seus discípulos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 46, 'Tomai cuidado com os escribas, que querem andar roupas compridas, e amam as saudações nas praças, e as primeiras cadeiras nas sinagogas, e os primeiros assentos nos jantares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 20, 47, 'Que devoram as casas das viúvas, e fingem fazer longas orações. Estes receberão mais grave condenação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 1, 'E ele, olhando, viu os ricos lançarem suas ofertas na arca do tesouro [do templo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 2, 'E viu também uma pobre viúva lançar ali duas pequenas moedas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 3, 'E disse: Em verdade vos digo que esta pobre viúva lançou mais do que todos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 4, 'Porque todos aqueles lançaram para as ofertas de Deus daquilo que lhes sobrava; mas esta [viúva] , de sua pobreza, lançou todo o sustento que tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 5, 'E alguns estavam falando do templo, que era adornado com formosas pedras e ofertas. Então [Jesus] disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 6, 'Destas coisas que vedes, dias virão, em que não se deixará pedra sobre pedra, que não seja derrubada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 7, 'E perguntaram-lhe, dizendo: Mestre, quando, pois, serão essas coisas? E que sinal haverá, quando essas coisas vierem a acontecer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 8, 'Então ele disse: Olhai para que não vos enganem, porque muitos virão em meu nome, dizendo: Eu sou [o Cristo] . E o tempo já está perto; portanto não os sigais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 9, 'E quando ouvirdes de guerras, e de rebeliões, não vos espanteis. Porque é necessário que estas coisas aconteçam primeiro; mas ainda não é o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 10, 'Então lhe disse: Então se levantará nação contra nação, e reino contra reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 11, 'E haverá em vários lugares grandes terremotos e fomes, e pragas; haverá também coisas espantosas, e grandes sinais do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 12, 'Mas antes de tudo isto, eles vos impedirão e vos perseguirão, [vos] entregando em sinagogas e prisões, [e] vos trazendo diante de reis, e governadores, por causa do meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 13, 'E isto vos acontecerá para haver testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 14, 'Portanto, que vós decidais nos vossos corações não planejar como direis em vossa defesa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 15, 'porque eu vos darei boca e sabedoria, para que todos os que forem contra vós não posam [vos] contradizer ou resistir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 16, 'E vós sereis entregues até pelos pais, e irmãos, e parentes, e amigos; e [alguns] de vós serão mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 17, 'E vós sereis odiados por todos por causa do meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 18, 'Mas nem um cabelo de vossa cabeça parecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 19, 'Por vossa paciência ganhareis vossas almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 20, 'Porém quando virdes a Jerusalém cercada de exércitos, sabei então, que próxima está sua desolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 21, 'Então, os que estiverem na Judeia, fujam para os montes; e os que estiverem no meio dela, saiam, e os que estiverem nos campos, não entrem nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 22, 'Porque estes são dias de vingança, para que todas as coisas que estão escritas se cumpram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 23, 'Mas ai das grávidas, e das que amamentarem naqueles dias; porque grande calamidade haverá na terra, e ira contra este povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 24, 'E cairão pela lâmina de espada, e serão levados cativos para todas as nações; e Jerusalém será pisada pelos gentios, até que os tempos dos gentios se cumpram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 25, 'E haverá sinais no Sol, [na] Lua, e [nas] estrelas; e na terra sofrimento entre as nações, como o rugir e agitar do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 26, 'As pessoas desmaiarão de medo e da expectativa das coisas que vão acontecer ao mundo, porque os poderes dos céus serão abalados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 27, 'E então verão o Filho do homem vir em uma nuvem com grande poder e glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 28, 'Ora, quando estas coisas começarem a acontecer, olhai para cima, e levantai vossas cabeças, porque vosso resgate está perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 29, 'E disse-lhes uma parábola: Olhai a figueira, e todas as árvores;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 30, 'Quando vós vedes elas já brotando, sabeis por vós mesmos que o verão já está perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 31, 'Assim também vós, quando virdes acontecer estas coisas, sabei que o Reino de Deus já está perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 32, 'Em verdade vos digo, que esta geração não passará, até que tudo aconteça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 33, 'O céu e a terra passarão, mas minhas palavras de maneira nenhuma passarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 34, 'E olhai por vós, para que vossos corações não venham a se encher de ressaca e embriaguez, e das preocupações d [esta] vida; e vos venha aquele dia de surpresa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 35, 'Porque virá como uma armadilha sobre todos os que habitam sobre a face de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 36, 'Então vigiai sempre, orando para que sejais considerados dignos de escaparem de todas as coisas que irão acontecer, e de ficarem de pé diante do Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 37, 'E ensinava durante os dias no Templo, porém, às noites saía e as passava no monte, chamado as Oliveiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 21, 38, 'E todo o povo vinha até ele de manhã cedo ao templo, para o ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 1, 'Estava perto a festa dos pães sem fermento, chamada de páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 2, 'E os chefes dos sacerdotes, e os escribas procuravam um meio de o matar, pois eles temiam ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 3, 'E Satanás entrou no Judas que era chamado Iscariotes, que era um dos doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 4, 'E foi, e falou com os chefes dos sacerdotes e os oficiais, sobre como [o] entregaria para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 5, 'E [estes] se alegraram, e concordaram em lhe dar dinheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 6, 'E [lhes] prometeu, e buscava oportunidade para o entregar quando não houvesse uma multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 7, 'E veio o dia dos [pães] sem fermento, em que se devia fazer o sacrifício da páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 8, 'E [Jesus] mandou a Pedro, e a João, dizendo: Ide, preparai-nos a páscoa, para que [a] comamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 9, 'E eles lhe disseram: Onde queres que [a] preparemos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 10, 'E ele lhes disse: Eis que, quando entrardes na cidade, um homem com um vaso de água vos encontrará; segui-o até a casa onde ele entrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 11, 'E direis ao dono da casa: O Mestre te diz: Onde está o salão onde comerei a páscoa com meus discípulos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 12, 'Então ele vos mostrará um grande salão já arrumado; preparai-a ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 13, 'E indo eles, acharam como lhes tinha dito; e prepararam a páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 14, 'E vinda a hora, sentou-se [à mesa] ,e com ele os doze apóstolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 15, 'E disse-lhes: Muito desejei comer convosco esta páscoa, antes que eu sofra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 16, 'Porque eu vos digo, que dela não mais comerei, até que [isto] se cumpra no Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 17, 'E tomando o copo, e tendo agradecido [a Deus] ,disse: Tomai-o, e reparti [-o] entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 18, 'Porque vos digo, que do fruto da videira eu não beberei, até que o Reino de Deus venha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 19, 'E tomando o pão, e tendo agradecido [a Deus] ,partiu-o, e o deu a eles, dizendo: Isto é o meu corpo, que é dado por vós; fazei isto em memória de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 20, 'De modo semelhante também com o copo, depois da ceia, disse: Este copo [é] o Novo Testamento em meu sangue, que é derramado por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 21, 'Porém eis que a mão do que me trai [está] comigo à mesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 22, 'E realmente o Filho do homem vai conforme o que está determinado; mas ai daquele homem por quem é traído!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 23, 'E começaram a perguntar entre si, qual deles seria o que faria isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 24, 'E houve também uma briga entre eles, sobre qual deles era considerado o maior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 25, 'E [Jesus] lhes disse: Os reis dos gentios os dominam, e os que exercem autoridade sobre eles são chamados de benfeitores;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 26, 'Mas não [seja] assim entre vós; antes o maior de vós seja como o menor; e o que lidera, como o que serve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 27, 'Porque qual é maior? O que se senta [à mesa] ,ou o que serve? Por acaso não é o que se senta [à mesa] ? Porém eu estou entre vós como aquele que serve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 28, 'E vós sois os que tendes permanecido comigo em minhas tentações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 29, 'E eu vos determino um Reino, assim como meu pai o determinou a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 30, 'Para que em meu Reino, comais e bebais à minha mesa; e vos senteis sobre tronos, julgando as doze tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 31, 'Disse também o Senhor: Simão, Simão; eis que Satanás vos pediu, para [vos] peneirar como trigo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 32, 'Mas eu roguei por ti, que tua fé não se acabe; e quando tu te converteres, fortaleça teus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 33, 'E ele lhe disse: Senhor, estou preparado para ir contigo até à prisão, e à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 34, 'Mas ele disse: Pedro, eu te digo que hoje o galo não cantará, antes que me negues três vezes que me conheces.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 35, 'E disse a eles: Quando vos mandei sem bolsa, e sem sacola, e sem sandálias, por acaso algo vos faltou?E disseram: Nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 36, 'Então, ele lhes disse: Mas agora, quem tem bolsa, tome-a, como também a sacola; e o que não tem espada, venda sua roupa, e compre uma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 37, 'Porque eu vos digo, que ainda é necessário que se cumpra em mim aquilo que está escrito: E ele foi contado com os malfeitores. Porque aquilo que é sobre mim tem que se cumprir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 38, 'E eles disseram: Senhor, eis aqui duas espadas.E ele lhes disse: É o suficiente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 39, 'E saindo, foi, como de costume, para o monte das Oliveiras; e os seus discípulos também o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 40, 'E quando chegou a aquele lugar, disse-lhes: Orai para que não entreis em tentação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 41, 'E se afastou deles, [à distância] de um tiro de pedra. E pondo-se de joelhos, orava,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 42, 'Dizendo: Pai, se tu quiseres, passa este copo de mim; porém não se faça minha vontade, mas a tua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 43, 'E apareceu-lhe um anjo do céu, que o fortalecia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 44, 'E estando em angústia, orava mais intensamente. E seu suor se fez como gotas de sangue, que desciam até o chão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 45, 'E ele, levantando-se da oração, veio a seus discípulos, e os achou dormindo por causa da tristeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 46, 'E disse-lhes: Por que estais dormindo? Levantai-vos, e orai, para que não entreis em tentação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 47, 'E enquanto ele ainda estava falando, eis que uma multidão [chegou] ; e um dos doze, o que se chamava Judas, ia adiante deles, e se aproximou de Jesus, para o beijar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 48, 'E Jesus lhe disse: Judas, com um beijo trais ao Filho do homem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 49, 'E os que estavam com ele, vendo o que iria acontecer, disseram-lhe: Senhor, feriremos com a espada?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 50, 'E um deles feriu a um servo do chefe dos sacerdotes, e cortou-lhe a orelha direita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 51, 'E respondendo Jesus, disse: Para com isto! E tocando-lhe a orelha, o curou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 52, 'E disse Jesus aos chefes dos sacerdotes, e aos oficiais do Templo, e aos anciãos, que tinham vindo contra ele: Como [se eu fosse] ladrão, saístes com espadas e bastões?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 53, 'Estando eu convosco todo dia no Templo, contra mim não me prendestes; mas esta é a vossa hora, e [sob] a autoridade das trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 54, 'E prendendo-o, [o] trouxeram e o puseram na casa do sumo sacerdote. E Pedro [o] seguia de longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 55, 'E acenderam fogo no meio do pátio, e sentaram-se juntos, e Pedro se sentou entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 56, 'E uma serva, vendo-o sentado junto ao fogo, fixando o olhos nele, disse: Este também estava com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 57, 'Porém ele o negou, dizendo: Mulher, eu não o conheço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 58, 'E pouco depois, outro o viu, e disse: Também tu és um deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 59, 'E quando já tinha passado quase uma hora, outro afirmava, dizendo: Verdadeiramente também este estava com ele, porque também é galileu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 60, 'E Pedro disse: Homem, não sei o que dizes.E logo, estando ele ainda falando, cantou o galo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 61, 'E o Senhor, virando-se, olhou para Pedro; e Pedro se lembrou da palavra do Senhor, como lhe tinha dito: Antes que o galo cante, tu me negarás três vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 62, 'E Pedro, saindo, chorou amargamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 63, 'E os homens que tinham prendido a Jesus zombavam dele, ferindo-o;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 64, 'E cobrindo-o, feriam-no no rosto; e perguntavam-lhe, dizendo: Profetiza, quem é o que te feriu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 65, 'E diziam muitas outras coisas contra ele, insultando-o.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 66, 'E quando já era de dia, juntaram-se os anciãos do povo, e os chefes dos sacerdotes, e os escribas, e o trouxeram ao supremo conselho,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 67, 'dizendo, Tu és o Cristo? Dize-nos. E ele lhes disse: Se eu vos disser, não o crereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 68, 'E também se eu perguntar, não me respondereis, nem [me] soltareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 69, 'A partir de agora o Filho do homem se sentará à direita do poder de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 70, 'E todos disseram: Então tu és o Filho de Deus?E ele lhes disse: Vós dizeis que eu sou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 22, 71, 'E eles disseram: Para que precisamos de mais testemunho? Pois nós mesmos o ouvimos de sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 1, 'E levantando-se toda a multidão deles, o levaram a Pilatos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 2, 'E começaram a acusá-lo, dizendo: Encontramos este [homem] ,que perverte a nação, e proíbe dar tributo a César, dizendo que ele mesmo é Cristo, o Rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 3, 'E Pilatos lhe perguntou, dizendo: Tu és o Rei dos judeus?E respondendo, ele lhe disse: Tu o dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 4, 'E Pilatos disse aos chefes dos sacerdotes, e às multidões: Não acho culpa nenhuma neste homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 5, 'Mas eles insistiam, dizendo: Ele incita ao povo, ensinando por toda a Judeia, começando desde a Galileia até aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 6, 'Então Pilatos, ouvindo [falar] da Galileia, perguntou se aquele homem era galileu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 7, 'E quando soube que era da jurisdição de Herodes, ele o entregou a Herodes, que naqueles dias também estava em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 8, 'E Herodes, ao ver Jesus, alegrou-se muito, porque havia muito tempo que desejava o ver, pois ouvia muitas coisas sobre ele; e esperava ver algum sinal feito por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 9, 'E perguntava-lhe com muitas palavras, mas ele nada lhe respondia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 10, 'E estavam [lá] os chefes dos sacerdotes, e os escribas, acusando-o com veemência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 11, 'E Herodes, com seus soldados, desprezando-o, e escarnecendo dele, o vestiu com uma roupa luxuosa, e o enviou de volta a Pilatos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 12, 'E no mesmo dia Pilatos e Herodes se fizeram amigos; porque antes tinham inimizade um contra o outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 13, 'E Pilatos, convocando aos chefes dos sacerdotes, aos líderes, e ao povo, disse-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 14, 'Vós me trouxestes a este homem, como que perverte o povo; e eis que eu, examinando-o em vossa presença, nenhuma culpa eu acho neste homem, das de que o acusais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 15, 'E nem também Herodes; porque a ele eu vos remeti; e eis que ele nada fez para que seja digno de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 16, 'Então eu o castigarei, e [depois] o soltarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 17, 'E ele tinha de soltar-lhes alguém durante a festa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 18, 'Porém todos clamavam juntos, dizendo: Tirai-o daqui! E soltai Barrabás para nós!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 19, '(O qual por uma rebelião feita na cidade, e [por] uma morte, tinha sido lançado na prisão).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 20, 'Pilatos falou-lhes então outra vez, querendo soltar Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 21, 'Mas eles clamavam, dizendo: Crucifica [-o] ! crucifica-o!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 22, 'E ele lhes disse a terceira vez: Pois que mal este fez? Nenhuma culpa de morte nele eu achei. Então eu o castigarei, e [depois] o soltarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 23, 'Mas eles continuavam, com grandes gritos, pedindo que fosse crucificado. E seus gritos, e [os] dos chefes dos sacerdotes, prevaleceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 24, 'Então Pilatos julgou que se fizesse o que pediam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 25, 'E soltou-lhes ao que fora lançado na prisão por uma rebelião e [uma] morte, que [era] o que pediam; porém a Jesus [lhes] entregou à sua vontade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 26, 'E enquanto o levavam, tomaram a um Simão Cireneu, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse atrás de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 27, 'E seguia-o uma grande multidão do povo, e de mulheres, as quais também ficavam desconsoladas, e lamentavam por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 28, 'E Jesus, virando-se para elas, disse: Filhas de Jerusalém, não choreis por mim, mas chorai por vós mesmas, e por vossos filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 29, 'Porque eis que vêm dias em que dirão: Bem-aventuradas as estéreis, e os ventres que não deram a luz, e os peitos que não amamentaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 30, 'Então começarão a dizer aos montes: Cai sobre nós; E aos morros: Cobri-nos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 31, 'Porque, se fazem isto à árvore verde, o que se fará com a [árvore] seca?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 32, 'E também levaram outros dois, que eram malfeitores, para matar com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 33, 'E quando chegaram ao lugar, chamado a Caveira, o crucificaram ali, e aos malfeitores, um à direita, e outro à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 34, 'E Jesus dizia: Pai, perdoa-lhes, porque não sabem o que fazem. E, repartindo suas roupas, lançaram sortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 35, 'E o povo estava olhando; e os líderes também zombavam com eles, dizendo: Salvou a outros, salve agora a si mesmo, se é o Cristo, o escolhido de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 36, 'E os soldados também escarneciam dele, aproximando-se dele, e mostrando-lhe vinagre;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 37, 'E dizendo: Se tu és o Rei dos judeus, salva a ti mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 38, 'E também estava acima dele um título escrito com letras gregas, romanas e hebraicas: ESTE É O REI DOS JUDEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 39, 'E um dos malfeitores que estavam pendurados o insultava, dizendo: Se tu és o Cristo, salva a ti mesmo, e a nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 40, 'Porém o outro, respondendo, repreendia-o, dizendo: Tu ainda não temes a Deus, [mesmo] estando na mesma condenação?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 41, 'E nós realmente [estamos sendo punidos] justamente, porque estamos recebendo de volta merecidamente por aquilo que praticamos; mas este nada fez de errado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 42, 'E disse a Jesus: Senhor, lembra-te de mim, quando chegares em teu Reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 43, 'E Jesus lhe disse: Em verdade te digo, hoje estarás comigo no paraíso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 44, 'E era já quase a hora sexta, e houve trevas em toda a terra, até a hora nona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 45, 'E o sol se escureceu, e o véu do templo se rasgou ao meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 46, 'E Jesus, clamando em alta voz, disse: Pai, em tuas mãos eu entrego meu espírito.E tendo dito isto, parou de respirar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 47, 'E o centurião, vendo o o que tinha acontecido, deu glória a Deus, dizendo: Verdadeiramente este homem era justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 48, 'E todas as multidões que se juntavam para observar, vendo o que tinha acontecido, voltaram, batendo nos peitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 49, 'E todos os seus conhecidos, e as mulheres que acompanhando [-o] desde a Galileia, tinham o seguido, estavam longe, vendo estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 50, 'E eis que um homem, de nome José, membro do conselho [de justiça] ,sendo homem bom e justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 51, '(Que não tinha concordado, nem com o conselho, nem em atos que fizeram), da cidade de Arimateia, [da terra] dos judeus, e que também esperava pelo Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 52, 'Este, chegando a Pilatos, pediu o corpo de Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 53, 'E tendo o tirado, o envolveu em um tecido de linho, e o pôs em um sepulcro, escavado em uma rocha, onde nunca ainda tinha sido posto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 54, 'E era o dia da preparação, e o sábado estava começando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 55, 'E as mulheres que vieram com ele da Galileia também [o] seguiram, e viram o sepulcro, e como seu corpo foi posto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 23, 56, 'E elas, ao voltarem, prepararam materiais aromáticos e óleos perfumados. E descansaram o sábado, conforme o mandamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 1, 'E no primeiro [dia] da semana, de madrugada bem cedo, foram ao sepulcro, levando [consigo] os materiais aromáticos que tinham preparado; e algumas [outras] junto delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 2, 'E acharam a pedra já revolvida do sepulcro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 3, 'E entrando, não acharam o corpo do Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 4, 'E aconteceu, que estando elas perplexas, eis que dois homens apareceram junto a elas, com roupas luminosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 5, 'E estando elas com muito medo, e abaixando o rosto para o chão, eles lhes disseram: Por que buscam entre os mortos aquele que vive?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 6, 'Ele não está aqui, mas já ressuscitou. Lembrai-vos de como ele vos falou, quando ainda estava na Galileia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 7, 'Dizendo: É necessário que o Filho do homem seja entregue nas mãos de homens pecadores, e [que] seja crucificado, e ressuscite ao terceiro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 42, 'Lucas', 'Lc', 24, 8, 'E se lembraram das palavras dele.')
